/* Админ-платформа */
const AD = 'Админ-платформа';
const ADM = ['admin'];
const rejBtn = (t) => btn('Отклонить', { cls: 'btn-sm btn-ghost', attrs: `data-act="modal" data-id="reject" data-title="${t}"` });
const okBtn = btn('Одобрить', { cls: 'btn-sm btn-primary', attrs: demo('Демо: одобрено, автор получит уведомление') });
route('/admin', { title: 'Админка: обзор', area: 'admin', need: ADM, group: AD, render: () => pageHead('Обзор', { sub: 'Что требует внимания сегодня. Цифры — пример.' }) + `<div class="tiles">
<a class="tile kpi ink" href="#/admin/queue" style="text-decoration:none"><span>В очереди модерации</span><b>5</b><span>старшая — 5 часов</span></a>
<a class="tile kpi" href="#/admin/complaints" style="text-decoration:none"><span>Новые жалобы</span><b>2</b><span>1 повторная (3 жалобы)</span></a>
<a class="tile kpi" href="#/admin/issues" style="text-decoration:none"><span>Открытые обращения</span><b>2</b><span>без ответственного: 1</span></a>
<a class="tile kpi" href="#/admin/business" style="text-decoration:none"><span>Заявки бизнеса</span><b>1</b><span>правка карточки</span></a>
<div class="tile kpi"><span>DAU / WAU / MAU</span><b>— / — / —</b><span>данных пока нет</span></div>
<div class="tile kpi"><span>Регистрации, 7 дней</span><b>—</b><span>данных пока нет</span></div>
<section class="tile w8"><div class="tile-h"><h2>Очередь модерации</h2><a class="more" href="#/admin/queue">Открыть${ic('arrow', 'i-s')}</a></div><div class="mini">${DATA.queue.slice(0, 3).map((q) => `<div class="r"><span>${badge(q.type)} ${q.title}</span><span class="meta">${q.ago}</span></div>`).join('')}</div></section>
<section class="tile"><div class="tile-h"><h2>Состояние системы</h2></div><div class="mini"><div class="r"><span>API и база</span>${badge('Работает', 'ok')}</div><div class="r"><span>Почта (SMTP)</span>${badge('Настроено', 'ok')}</div><div class="r"><span>Резервная копия</span><span class="meta">сегодня 03:00 (пример)</span></div></div></section></div>` });
route('/admin/queue', { title: 'Очередь модерации', area: 'admin', need: ADM, group: AD, render: () => pageHead('Очередь модерации', { sub: 'Единая очередь всех типов — концепция: сейчас в продукте очереди разнесены по 4 разделам.', actions: concept() }) + `<div class="toolbar"><div class="stabs" role="tablist">${['Все · 5', 'Объявления', 'Посты', 'Вакансии и находки', 'Бизнес'].map((t, i) => `<button role="tab" data-act="tab" data-group="qf" data-val="${i}" aria-selected="${i === 0}">${t}</button>`).join('')}</div><span class="grow"></span>${btn('Одобрить выбранные', { cls: 'btn-sm btn-secondary', attrs: demo('Демо: массовые действия — концепция') })}</div>` +
  st(() => `<div class="tbl-wrap"><table class="tbl"><thead><tr><th><span class="sr">Выбор</span></th><th>Запись</th><th>Тип</th><th>Автор</th><th>Ждёт</th><th></th></tr></thead><tbody>${DATA.queue.map((q) => `<tr><td><input type="checkbox" aria-label="Выбрать ${q.title}" style="width:20px;height:20px"></td><td><b>${q.title}</b>${q.flag ? `<br>${badge(q.flag, 'warn')}` : ''}</td><td data-l="Тип">${q.type}</td><td data-l="Автор">${q.author}</td><td data-l="Ждёт">${q.ago}</td><td class="tact">${btn('Открыть', { cls: 'btn-sm btn-ghost', attrs: 'data-act="modal" data-id="qitem" data-title="' + q.title + '"' })}${okBtn}${rejBtn(q.title)}</td></tr>`).join('')}</tbody></table></div>`, ['Очередь пуста', 'Все публикации проверены. Новые появятся здесь автоматически.']) });
MODALS.qitem = (d) => `<h2>${d.title}</h2><div class="gallery">${photo('sky')}</div><p>Текст публикации (пример). Модератор видит только эту запись.</p><dl class="kv"><dt>Автор</dt><dd>Новый автор · 0 одобренных</dd><dt>Порог доверия</dt><dd>3 одобренных без отклонений</dd></dl><div class="row-btns end">${rejBtn(d.title)}${okBtn}</div>`;
route('/admin/complaints', { title: 'Жалобы', area: 'admin', need: ADM, group: AD, render: () => pageHead('Жалобы') + st(() => `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>На что</th><th>Причина</th><th>Жалоб</th><th>Статус</th><th></th></tr></thead><tbody>${DATA.complaints.map((c) => `<tr><td><b>${c.on}</b><br><span class="meta">${c.ago}</span></td><td data-l="Причина">${c.reason}</td><td data-l="Жалоб">${c.count}</td><td data-l="Статус">${badge(c.status, c.tone)}</td><td class="tact">${btn('Снять запись', { cls: 'btn-sm btn-ghost', attrs: 'data-act="modal" data-id="reject" data-title="' + c.on + '"' })}${btn('Отклонить жалобу', { cls: 'btn-sm btn-secondary', attrs: demo('Демо: жалоба отклонена') })}</td></tr>`).join('')}</tbody></table></div><p class="meta">Из личной переписки модератор видит только сообщение, на которое пожаловались (до 500 символов).</p>`, ['Жалоб нет', 'Новые жалобы появятся здесь.']) });
const kinds = { news: 'Новости', events: 'События', orgs: 'Организации и услуги', directory: 'Справочник' };
route('/admin/content/:kind', { title: 'CMS: список', area: 'admin', need: ADM, group: AD, sample: '/admin/content/news', navKeyFn: true, render: (p) => { const k = kinds[p.kind] ? p.kind : 'news'; const rows = k === 'news' ? DATA.news.map((n) => [n.title, n.cat, 'Опубликовано', 'ok']) : k === 'events' ? DATA.events.map((e) => [e.title, e.d + ' · ' + e.w, 'Опубликовано', 'ok']) : k === 'orgs' ? DATA.orgs.map((o) => [o.name, o.cat, o.verified ? 'Опубликовано' : 'Черновик', o.verified ? 'ok' : '']) : DATA.directory.flatMap((g) => g.items.map(([t]) => [t, g.group, 'Опубликовано', 'ok']));
  return pageHead(kinds[k], { actions: btn('Создать', { href: '#/admin/content/' + k + '/edit', cls: 'btn-primary', icon: 'plus' }) }) + `<div class="toolbar"><label class="fld grow"><span class="sr">Поиск</span><input placeholder="Поиск по заголовку"></label><label class="fld"><span class="sr">Статус</span><select><option>Все статусы</option><option>Черновик</option><option>Опубликовано</option><option>Снято</option></select></label></div>` + st(() => `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Заголовок</th><th>Рубрика</th><th>Статус</th><th></th></tr></thead><tbody>${rows.map(([t, c, s, tn]) => `<tr><td><b>${t}</b></td><td data-l="Рубрика">${c}</td><td data-l="Статус">${badge(s, tn)}</td><td class="tact">${btn('Изменить', { href: '#/admin/content/' + k + '/edit', cls: 'btn-sm btn-ghost' })}${btn('Снять', { cls: 'btn-sm btn-ghost', attrs: demo('Демо: снято с публикации') })}</td></tr>`).join('')}</tbody></table></div>`, ['Записей нет', 'Создайте первую — она появится на сайте после публикации.']); } });
route('/admin/content/:kind/edit', { title: 'CMS: редактор', area: 'admin', need: ADM, group: AD, sample: '/admin/content/news/edit', render: (p) => pageHead('Редактор', { crumbs: [[kinds[p.kind] || 'Новости', '#/admin/content/' + p.kind], ['Запись']] }) + `<div class="editor"><form class="form card" data-form data-ok="Демо: опубликовано" style="max-width:none">${field('Заголовок', { req: true, val: DATA.news[0].title })}${field('Лид', { type: 'textarea', rows: 2, val: DATA.news[0].lead })}${field('Текст', { type: 'textarea', rows: 10, req: true, val: 'Текст материала…' })}<div class="upload">${ic('image')}Обложка и фото</div><div class="row-btns">${btn('Опубликовать', { type: 'submit', cls: 'btn-primary' })}${btn('Сохранить черновик', { attrs: demo('Демо: черновик') })}${btn('Предпросмотр', { href: '#/news/1' })}</div></form>
<aside class="lst"><div class="card"><h3>Публикация</h3>${field('Статус', { type: 'select', opts: ['Черновик', 'Опубликовано', 'Снято'] })}${field('Рубрика', { type: 'select', opts: ['Важное', 'Благоустройство', 'Транспорт'] })}${field('Источник', { ph: 'Кто сообщил' })}</div><div class="card"><h3>История версий</h3>${concept()}</div></aside></div>` });
route('/admin/categories', { title: 'Категории', area: 'admin', need: ADM, group: AD, render: () => pageHead('Категории', { actions: btn('Добавить', { cls: 'btn-primary', icon: 'plus', attrs: demo('Демо: форма категории') }) }) + `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Категория</th><th>Раздел</th><th></th></tr></thead><tbody>${DATA.cats.map((c) => `<tr><td><b>${c}</b></td><td data-l="Раздел">Организации и услуги</td><td class="tact">${btn('Изменить', { cls: 'btn-sm btn-ghost', attrs: demo('Демо') })}</td></tr>`).join('')}</tbody></table></div>` });
route('/admin/issues', { title: 'Обращения', area: 'admin', need: ADM, group: AD, render: () => pageHead('Обращения жителей', { sub: 'Минимально необходимые данные автора. Внешним органам автоматически не передаются.' }) + st(() => `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>№</th><th>Тема</th><th>Статус</th><th>Ответственный</th><th></th></tr></thead><tbody>${DATA.issues.map((i, k) => `<tr><td>${i.id}</td><td data-l="Тема"><b>${i.title}</b></td><td data-l="Статус">${badge(i.status, i.tone)}</td><td data-l="Ответственный">${k === 1 ? '<span class="meta">не назначен</span>' : 'Поддержка (пример)'}</td><td class="tact">${btn('Открыть', { href: '#/admin/issues/' + i.id, cls: 'btn-sm btn-ghost' })}</td></tr>`).join('')}</tbody></table></div>`, ['Обращений нет', 'Новые обращения жителей появятся здесь.']) });
route('/admin/issues/:id', { title: 'Обращение (админ)', area: 'admin', need: ADM, group: AD, sample: '/admin/issues/42', navKey: '/admin/issues', render: (p) => { const i = DATA.issues.find((x) => x.id == p.id) || DATA.issues[0]; return pageHead('Обращение № ' + i.id, { crumbs: [['Обращения', '#/admin/issues'], ['№ ' + i.id]] }) + `<div class="editor"><div class="card"><h2>${i.title}</h2><p>Описание от жителя (пример).</p>${photo('sky')}<h3 style="margin-top:16px">История</h3><div class="mini"><div class="r"><span>Принято</span><span class="meta">2 дня назад</span></div><div class="r"><span>В работе · комментарий: «Передали электрику»</span><span class="meta">вчера</span></div></div><form class="form" data-form data-ok="Демо: комментарий отправлен жителю" style="margin-top:12px">${field('Комментарий для жителя', { type: 'textarea', rows: 3, req: true })}${btn('Отправить', { type: 'submit', cls: 'btn-primary' })}</form></div>
<aside class="card"><h3>Управление</h3>${field('Статус', { type: 'select', opts: ['Принято', 'В работе', 'Решено', 'Отклонено'] })}${field('Ответственный', { type: 'select', opts: ['Не назначен', 'Поддержка (пример)', 'Модератор (пример)'], help: 'Выбор из списка — концепция: в продукте сейчас только через API' })}${field('Публичность', { type: 'select', opts: ['Приватное', 'Публичное без имени'] })}${btn('Сохранить', { cls: 'btn-primary', attrs: demo('Демо: сохранено, житель получит уведомление') })}</aside></div>`; } });
route('/admin/polls', { title: 'Опросы (админ)', area: 'admin', need: ADM, group: AD, render: () => pageHead('Опросы', { actions: btn('Новый опрос', { cls: 'btn-primary', icon: 'plus', attrs: demo('Демо: редактор опроса') }) }) + `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Опрос</th><th>Голосов</th><th>Режим</th><th>Статус</th></tr></thead><tbody><tr><td><b>${DATA.poll.title}</b></td><td data-l="Голосов">${DATA.poll.votes}</td><td data-l="Режим">Анонимный</td><td data-l="Статус">${badge('Идёт', 'ok')}</td></tr><tr><td><b>Детская площадка (пример)</b></td><td data-l="Голосов">64</td><td data-l="Режим">Открытый</td><td data-l="Статус">${badge('Завершён')}</td></tr></tbody></table></div><p class="meta">В анонимном режиме имена проголосовавших не видны даже сотрудникам.</p>` });
route('/admin/groups', { title: 'Группы и лента (админ)', area: 'admin', need: ADM, group: AD, render: () => pageHead('Группы и лента') + tabs('ag', [['g', 'Группы на проверке'], ['p', 'Посты на проверке']], 'g') + panel('ag', 'g', `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Группа</th><th>Тип</th><th>Создатель</th><th></th></tr></thead><tbody><tr><td><b>Рыбалка (пример)</b></td><td data-l="Тип">Открытая</td><td data-l="Создатель">Житель</td><td class="tact">${okBtn}${rejBtn('Рыбалка')}</td></tr></tbody></table></div>`, 'g') + panel('ag', 'p', `<div class="tbl-wrap"><table class="tbl"><tbody><tr><td><b>Обмен семенами в субботу</b><br><span class="meta">Садоводы · новый автор</span></td><td class="tact">${okBtn}${rejBtn('пост')}</td></tr></tbody></table></div>`, 'g') });
route('/admin/business', { title: 'Заявки бизнеса', area: 'admin', need: ADM, group: AD, render: () => pageHead('Заявки бизнеса', { sub: 'Новые карточки и правки опубликованных. Правка публикуется только после одобрения.' }) + st(() => `<div class="lst">${[['Новая карточка', 'Детская студия (пример)', 'Детям и образование'], ['Правка опубликованной', 'Мастер на час (пример)', 'Изменены часы работы и описание']].map(([t, n, d]) => `<article class="card"><div class="status-row">${badge(t, 'warn')}<span class="meta">3 часа назад</span></div><h3 style="margin:8px 0">${n}</h3><p class="meta">${d}</p>${t.startsWith('Правка') ? `<div class="form-2"><div class="alert">${'<div><b>Было</b><p>пн–пт 9–18</p></div>'}</div><div class="alert ok"><div><b>Стало</b><p>пн–сб 9–19</p></div></div></div>` : ''}<div class="row-btns">${okBtn}${rejBtn(n)}</div></article>`).join('')}</div>`, ['Заявок нет', 'Новые заявки владельцев появятся здесь.']) });
route('/admin/users', { title: 'Пользователи и роли', area: 'admin', need: ADM, group: AD, render: () => pageHead('Пользователи и роли') + `<div class="toolbar"><label class="fld grow"><span class="sr">Поиск</span><input placeholder="Имя или email"></label><label class="fld"><span class="sr">Роль</span><select><option>Все роли</option>${['Житель', 'Поддержка', 'Редактор', 'Модератор', 'Администратор'].map((r) => `<option>${r}</option>`).join('')}</select></label></div>` + st(() => `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Пользователь</th><th>Роли</th><th>Статус</th><th>С нами</th><th></th></tr></thead><tbody>${DATA.users.map((u, i) => `<tr><td><b>${u.name}</b><br><span class="meta">${u.email}</span></td><td data-l="Роли">${u.roles}</td><td data-l="Статус">${badge(u.status, u.tone)}</td><td data-l="С нами">${u.since}</td><td class="tact">${btn('Открыть', { href: '#/admin/users/' + i, cls: 'btn-sm btn-ghost' })}</td></tr>`).join('')}</tbody></table></div>`, ['Никого не нашли', 'Измените запрос или фильтр роли.']) });
route('/admin/users/:id', { title: 'Пользователь', area: 'admin', need: ADM, group: AD, sample: '/admin/users/1', navKey: '/admin/users', render: (p) => { const u = DATA.users[p.id] || DATA.users[1]; return pageHead(u.name, { crumbs: [['Пользователи', '#/admin/users'], [u.name]] }) + `<div class="editor"><div class="lst"><div class="card"><h3>Роли</h3>${['Житель', 'Поддержка', 'Редактор', 'Модератор', 'Администратор'].map((r, i) => `<div class="flag-row"><span>${r}${i === 4 ? '<br><small class="meta">выдаёт только Super Admin</small>' : ''}</span><span></span><button class="switch" aria-label="${r}" aria-pressed="${u.roles.includes(r)}" ${i === 0 || i === 4 ? 'disabled' : 'data-act="toggle" data-msg-on="Демо: роль выдана, запись в журнале аудита" data-msg-off="Демо: роль снята, запись в журнале аудита"'}></button></div>`).join('')}</div><div class="card"><h3>Активность</h3><div class="mini"><div class="r"><span>Публикаций</span><b>4</b></div><div class="r"><span>Жалоб на пользователя</span><b>0</b></div></div></div></div>
<aside class="card"><h3>Аккаунт</h3><dl class="kv"><dt>Email</dt><dd>${u.email}</dd><dt>Подтверждён</dt><dd>да</dd></dl><div class="row-btns">${btn('Завершить все сессии', { cls: 'btn-sm btn-secondary', attrs: demo('Демо: сессии завершены') })}${btn('Заблокировать', { cls: 'btn-sm btn-danger', attrs: 'data-act="modal" data-id="danger" data-title="Заблокировать ' + u.name + '?" data-text="Пользователь не сможет войти, публикации будут скрыты. Действие записывается в журнал аудита." data-word="БЛОК" data-btn="Заблокировать" data-ok="Демо: ничего не изменено"' })}</div></aside></div>`; } });
route('/admin/analytics', { title: 'Аналитика', area: 'admin', need: ADM, group: AD, render: () => pageHead('Аналитика', { sub: 'Только агрегаты: без IP, браузера и id пользователя. Учитывается запрет отслеживания (DNT/GPC). Часовой пояс — Новосибирск.' }) + `<div class="tiles">${[['DAU', '—'], ['WAU', '—'], ['MAU', '—']].map(([t, v]) => `<div class="tile kpi"><span>${t}</span><b>${v}</b><span>данных пока нет</span></div>`).join('')}<section class="tile w8"><h2>Просмотры по разделам (макет)</h2><div class="bars" aria-hidden="true">${[60, 45, 30, 25, 20, 15].map((v) => `<i style="height:${v}%"></i>`).join('')}</div><p class="meta">Новости · Объявления · Услуги · События · Сообщество · Поиск — пример.</p></section><section class="tile"><h2>Поиск без результатов</h2><p class="meta">Запросы с телефоном, email или ссылкой не сохраняются.</p><div class="mini"><div class="r"><span>«баня»</span><span>—</span></div><div class="r"><span>«такси»</span><span>—</span></div></div></section></div>` });
route('/admin/audit', { title: 'Журнал аудита', area: 'admin', need: ADM, group: AD, render: () => pageHead('Журнал аудита', { sub: 'Только добавление записей — изменить или удалить нельзя. Тексты сообщений и постов не пишутся.' }) + `<div class="toolbar"><label class="fld grow"><span class="sr">Действие</span><input placeholder="Действие, например announcement.approve"></label><label class="fld"><span class="sr">Кто</span><select><option>Все сотрудники</option></select></label><label class="fld"><span class="sr">Период</span><select><option>7 дней</option><option>30 дней</option></select></label></div>` + st(() => `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Время</th><th>Кто</th><th>Действие</th><th>Объект</th></tr></thead><tbody>${DATA.audit.map(([t, w, a, o]) => `<tr><td>${t}</td><td data-l="Кто">${w}</td><td data-l="Действие"><code>${a}</code></td><td data-l="Объект">${o}</td></tr>`).join('')}</tbody></table></div><p class="meta">Полнотекстовый поиск по журналу — концепция.</p>`, ['Записей нет', 'За выбранный период действий не было.']) });
route('/admin/settings', { title: 'Настройки и функции', area: 'admin', need: ADM, group: AD, render: () => pageHead('Настройки и функции') + tabs('as', [['f', 'Функции'], ['m', 'Модерация'], ['i', 'Интеграции']], 'f') +
  panel('as', 'f', `<div class="card">${DATA.features.map(([t, s, on]) => `<div class="flag-row"><span><b>${t}</b><br><small class="meta">${s === 'available' ? 'доступно' : s === 'not_configured' ? 'не настроено: нужен провайдер и ваше согласование' : 'не реализовано'}</small></span>${badge(s === 'available' ? 'Доступно' : s === 'not_configured' ? 'Не настроено' : 'Нет в продукте', s === 'available' ? 'ok' : '')}<button class="switch" aria-label="${t}" aria-pressed="${on}" ${s === 'available' ? 'data-act="toggle" data-msg-on="Демо: включено, запись в аудите" data-msg-off="Демо: раздел скрыт, сервер отвечает 404"' : 'disabled'}></button></div>`).join('')}</div>`, 'f') +
  panel('as', 'm', `<form class="form card" data-form data-ok="Демо: сохранено, запись в аудите">${field('Порог доверия', { type: 'number', val: '3', help: 'Сколько одобренных публикаций без отклонений нужно для публикации без проверки. 0 — без премодерации.' })}${field('Срок объявлений, дней', { type: 'number', val: '30' })}${field('Хранение аналитики, дней', { type: 'number', val: '180' })}${btn('Сохранить', { type: 'submit', cls: 'btn-primary' })}</form>`, 'f') +
  panel('as', 'i', `<div class="card">${[['Почта (SMTP)', true], ['AI-провайдер', false], ['Платёжный сервис', false], ['Карты', false], ['Push', false], ['Вход через VK / Telegram', false], ['Внешний мониторинг', false]].map(([t, ok]) => `<div class="flag-row"><span>${t}</span><span></span>${badge(ok ? 'Настроено' : 'Не настроено', ok ? 'ok' : '')}</div>`).join('')}<p class="meta">Ключи хранятся на сервере и здесь не показываются.</p></div>`, 'f') });
